function loadNamecardEnv() {
  // watch_and_extract.py 需要的 ANTHROPIC_API_KEY / NAMECARD_FOLDER 等變數只存在
  // namecard-db/.env（shell export格式），這支hook是獨立spawn出去的子行程，
  // 不會自動繼承，要自己讀進來塞進spawn的env，不然子行程會因為缺變數直接失敗。
  const envPath = path.join(NAMECARD_DB_DIR, ".env");
  const merged = { ...process.env };
  try {
    const content = fs.readFileSync(envPath, "utf-8");
    for (const line of content.split("\n")) {
      const m = line.match(/^export\s+([A-Z_]+)="(.*)"\s*$/);
      if (m) merged[m[1]] = m[2];
    }
  } catch (e) {
    log(`TRIGGER 讀不到.env: ${e && e.message}`);
  }
  return merged;
}

function triggerExtractOnce() {
  try {
    const logFd = fs.openSync(path.join(NAMECARD_DB_DIR, "watch.log"), "a");
    const child = spawn(NAMECARD_PYTHON, ["watch_and_extract.py", "--once"], {
      cwd: NAMECARD_DB_DIR,
      env: loadNamecardEnv(),
      detached: true,
      stdio: ["ignore", logFd, logFd],
    });
    child.unref();
    log(`TRIGGER 已叫辨識程式立刻跑一次（PID ${child.pid}），事件觸發，沒有背景排程`);
  } catch (e) {
    log(`TRIGGER 啟動失敗: ${e && e.message}`);
  }
}

